def compute(vars):
    costs = vars["v1"]
    proceeds = vars["v2"]
    if proceeds == 0:
        return None

    ratio = costs / proceeds
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
